        line_num=idx+1
        m=re.match(r'^[ ]{0,3}(#{1,6})[ \t]+(.*)$', line)
        if m:
            level=len(m.group(1))
            title=m.group(2).strip()
            next_offset=offset+len(line)
            headings.append({
                'level': level,
                'title': title,
                'line_num': line_num,
                'heading_offset': offset,
                'next_offset': next_offset,
                'position_line': line_num+1,
                'position_offset': next_offset,
            })
        offset+=len(line)
    return headings

def extract_section(content, heading_name):
    headings=parse_headings(content)
    # find heading case-insensitive exact match
    target=None
    for h in headings:
        if h['title'].lower() == heading_name.lower():
            target=h
            break
    if not target:
        return None
    # find next heading with level <= target level
    start = target['heading_offset']
    # end is start of next heading with level <= target level
    end = len(content)
    found=False
    for h in headings:
        if h['heading_offset'] <= start:
            continue
        if h['level'] <= target['level']:
            end = h['heading_offset']
            break
    return content[start:end].strip()

