        print(f"For more information, try '--help'.", file=sys.stderr)
        sys.exit(2)

    if parsed.level is not None:
        try:
            int(parsed.level)
        except ValueError:
            print(f"error: invalid value '{parsed.level}' for '--level <LEVEL>'", file=sys.stderr)
            sys.exit(2)

    qout=parsed.query_output
    if qout not in ["plain","json","jsonl","md","tree","json-pretty"]:
        print(f"Error: Unknown output format: {qout}", file=sys.stderr)
        sys.exit(1)

    is_list = parsed.list
    is_tree = parsed.tree
    is_count = parsed.count
    is_section = parsed.section is not None
    is_query = parsed.query is not None

    has_cli = is_list or is_tree or is_count or is_section or is_query

    if not has_cli:
        print("Failed to enable raw mode: Cannot open /dev/tty: No such device or address (os error 6). Interactive mode requires a terminal.", file=sys.stderr)
        print("Note: When piping input, ensure you have a controlling terminal.", file=sys.stderr)
        print("Error: ", file=sys.stderr)
        print("   0: \x1b[91mCannot open /dev/tty: No such device or address (os error 6). Interactive mode requires a terminal.\x1b[0m", file=sys.stderr)
        print("", file=sys.stderr)
        print("Location:", file=sys.stderr)
        print("   \x1b[35msrc/main.rs\x1b[0m:\x1b[35m275\x1b[0m", file=sys.stderr)
        print("", file=sys.stderr)
        print("Backtrace omitted. Run with RUST_BACKTRACE=1 environment variable to display it.", file=sys.stderr)
        print("Run with RUST_BACKTRACE=full to include source snippets.", file=sys.stderr)
        sys.exit(1)

    nodes, headings, content, meta, err, first_path = load_first_file(file_list)

    if err:
        print(err, file=sys.stderr)
        sys.exit(1)

    if is_count:
        print(render_count(nodes))
        return

    if is_section and not is_query:
        if meta['headingCount']==1 and nodes[0]['title']=="Select a file":
            print(f"Section '{parsed.section}' not found", file=sys.stderr)
            sys.exit(1)
        flat=flatten_nodes(nodes)
        target=None
        for n in flat:
            if n['title'].lower() == parsed.section.lower():
                target=n
                break
        if not target:
