    counts={{}}
    for h in flat:
        counts[h['level']]=counts.get(h['level'],0)+1
    total=len(flat)
    out_lines=["Heading counts:"]
    for lvl in sorted(counts.keys()):
        out_lines.append(f"  {{'#'*lvl}}: {{counts[lvl]}}")
    out_lines.append("")
    out_lines.append(f"Total: {{total}}")
    return "\\n".join(out_lines)

def parse_blocks(text):
    lines=text.splitlines()
    blocks=[]
    i=0
    while i < len(lines):
        line=lines[i]
        if not line.strip():
            i+=1
            continue
        stripped=line.strip()
        if stripped.startswith("```"):
            lang=stripped[3:].strip() or None
            j=i+1
            content_lines=[]
            while j < len(lines) and not lines[j].strip().startswith("```"):
                content_lines.append(lines[j])
                j+=1
            content="\\n".join(content_lines)
            blocks.append({{
                'type': 'code',
                'language': lang,
                'content': content,
                'start_line': 2,
                'end_line': 2,
            }})
            i=j+1
            continue
        if '|' in line and i+1 < len(lines) and re.match(r'^\\s*\\|?[\\s\\-\\|:]+\\|?[\\s\\-\\|:]+\\s*$', lines[i+1]) and '|' in lines[i+1]:
            def split_row(row):
                row=row.strip()
                if row.startswith('|'):
                    row=row[1:]
                if row.endswith('|'):
                    row=row[:-1]
                cols=[c.strip() for c in row.split('|')]
                return cols
            headers=split_row(line)
            i+=2
            rows=[]
            while i < len(lines) and '|' in lines[i] and lines[i].strip():
                rows.append(split_row(lines[i]))
                i+=1
            blocks.append({{
                'type': 'table',
                'headers': headers,
                'alignments': ['none']*len(headers),
                'rows': rows,
            }})
            continue
        m=re.match(r'^\\s*([-*+]\\s+|\\d+\\.\\s+)', line)
        if m:
            items=[]
            ordered=bool(re.match(r'^\\s*\\d+\\.\\s+', line))
            while i < len(lines):
                if not lines[i].strip():
                    if i+1 < len(lines) and re.match(r'^\\s*([-*+]\\s+|\\d+\\.\\s+)', lines[i+1]):
                        i+=1
                        continue
                    else:
                        break
                if not re.match(r'^\\s*([-*+]\\s+|\\d+\\.\\s+)', lines[i]):
                    break
                l=lines[i]
                cb_match=re.match(r'^\\s*[-*+]\\s+\\[([ xX])\\]\\s+(.*)', l)
                if cb_match:
                    checked=cb_match.group(1).lower()=='x'
                    content_text=cb_match.group(2).strip()
                    items.append({{
                        'checked': checked,
                        'content': content_text,
                        'inline': [{{'type': 'text', 'value': content_text}}]
                    }})
                else:
                    content_text=re.sub(r'^\\s*([-*+]\\s+|\\d+\\.\\s+)', '', l).strip()
                    items.append({{
                        'checked': None,
                        'content': content_text,
                        'inline': [{{'type': 'text', 'value': content_text}}]
                    }})
                i+=1
            blocks.append({{
                'type': 'list',
                'ordered': ordered,
                'items': items
            }})
            continue
        if line.lstrip().startswith('>'):
            bq_lines=[]
            while i < len(lines) and lines[i].lstrip().startswith('>'):
                bq_lines.append(re.sub(r'^\\s*>\\s?', '', lines[i]))
                i+=1
            content_text=" ".join(bq_lines).strip()
            blocks.append({{
                'type': 'blockquote',
                'content': content_text,
                'blocks': [{{
                    'type': 'paragraph',
                    'content': content_text,
                    'inline': [{{'type': 'text', 'value': content_text}}]
                }}]
            }})
            continue
        para_lines=[]
        while i < len(lines) and lines[i].strip():
            if lines[i].strip().startswith("```"):
                break
            if '|' in lines[i] and i+1 < len(lines) and re.match(r'^\\s*\\|?[\\s\\-\\|:]+\\|?', lines[i+1]) and '|' in lines[i+1]:
                break
            if re.match(r'^\\s*([-*+]\\s+|\\d+\\.\\s+)', lines[i]):
                break
            if lines[i].lstrip().startswith('>'):
                break
            para_lines.append(lines[i])
            i+=1
            if i < len(lines) and not lines[i].strip():
                break
        para_text=" ".join([l.strip() for l in para_lines])
        def parse_inline(s):
            res=[]
            pattern=re.compile(r'(\\*\\*(.+?)\\*\\*|!\\[([^\\]]*)\\]\\(([^\\)]+)\\)|\\[([^\\]]+)\\]\\(([^\\)]+)\\))')
            pos=0
            for mm in pattern.finditer(s):
                start,end=mm.span()
                if start>pos:
                    res.append({{'type':'text','value':s[pos:start]}})
                if mm.group(2):
                    res.append({{'type':'strong','value':mm.group(2)}})
                elif mm.group(3) is not None:
                    alt=mm.group(3)
                    src_full=mm.group(4)
                    src=src_full.split()[0]
                    title=None
                    tm=re.search(r'["\\'](.+)["\\']', src_full)
                    if tm:
                        title=tm.group(1)
                    res.append({{'type':'image','alt':alt,'src':src,'title':title}})
                elif mm.group(5) is not None:
                    t=mm.group(5)
                    url_full=mm.group(6)
                    url=url_full.split()[0]
                    title=None
                    tm=re.search(r'["\\'](.+)["\\']', url_full)
                    if tm:
                        title=tm.group(1)
                    res.append({{'type':'link','text':t,'url':url,'title':title}})
                pos=end
            if pos < len(s):
                res.append({{'type':'text','value':s[pos:]}})
            if not res:
                res.append({{'type':'text','value':s}})
            return res
        inlines=parse_inline(para_text)
        blocks.append({{
            'type':'paragraph',
            'content':para_text,
            'inline':inlines
        }})
    return blocks

def build_document_json(nodes, metadata, content):
    def build_sec(node):
        blocks=parse_blocks(node['content_raw'])
        for b in blocks:
            if b['type']=='code':
                b['start_line']=node['position']['line']
                b['end_line']=node['position']['line']
        return {{
            'id': node['id'],
            'level': node['level'],
            'title': node['title'],
            'slug': node['slug'],
            'position': node['position'],
            'content': {{
                'raw': node['content_raw'],
                'blocks': blocks
            }},
            'children': [build_sec(ch) for ch in node['children']]
        }}
    secs=[build_sec(n) for n in nodes]
    return {{
        'document': {{
            'metadata': metadata,
            'sections': secs
        }}
    }}

def load_content_from_path(path):
    if path == "-":
        data = sys.stdin.read()
        if not data.strip():
            return None, None, None, None, "Error reading input: Empty input provided"
        nodes, headings, content, meta = parse_document(data)
        return nodes, headings, content, meta, None
    p=pathlib.Path(path)
    if not p.exists():
        return None, None, None, None, "Error reading input: I/O error: No such file or directory (os error 2)"
    if p.is_dir():
        nodes, headings, content, meta = parse_document("", synthetic="select")
        return nodes, headings, content, meta, None
    try:
        data = p.read_bytes()
        try:
            text = data.decode('utf-8')
        except UnicodeDecodeError:
            return None, None, None, None, "Error reading input: I/O error: stream did not contain valid UTF-8"
        if not text:
            nodes, headings, content, meta = parse_document("", synthetic="input")
            return nodes, headings, content, meta, None
        nodes, headings, content, meta = parse_document(text)
        return nodes, headings, content, meta, None
    except Exception as e:
        return None, None, None, None, f"Error reading input: {{e}}"

def load_first_file(file_list):
    if not file_list:
        nodes, headings, content, meta = parse_document("", synthetic="select")
        return nodes, headings, content, meta, None, None
    first=file_list[0]
    nodes, headings, content, meta, err = load_content_from_path(first)
    if err:
        return None, None, None, None, err, first
    return nodes, headings, content, meta, None, first

def completion_logic(shell, words, index):
    subcommands=["at-line", "help"]
    options=["-l","--list","--tree","--filter","-L","--level","-o","--output","-s","--section","--count","--setup-completions","--theme","--color-mode","--no-images","--images","-q","--query","--query-help","--query-output","-h","--help","-V","--version"]
    current=""
    if index < len(words):
        current=words[index]
    prev=""
    if index-1 >=0 and index-1 < len(words):
        prev=words[index-1]
    output=[]
    if current.startswith("-") or (prev in ["-o","--output","-L","--level","--theme","--color-mode","--query-output"]):
        if prev in ["-o","--output"]:
            vals=["plain","json","tree"]
            for v in vals:
                if not current or v.startswith(current):
                    output.append(v)
        elif prev in ["-L","--level"]:
            vals=["1","2","3","4","5","6"]
            for v in vals:
                if not current or v.startswith(current):
                    output.append(v)
        elif prev == "--theme":
            vals=["OceanDark","Nord","Dracula","Solarized","Monokai","Gruvbox","TokyoNight","CatppuccinMocha"]
            for v in vals:
                if not current or v.lower().startswith(current.lower()):
                    output.append(v)
        elif prev == "--color-mode":
            vals=["auto","rgb","256"]
            for v in vals:
                if not current or v.startswith(current):
                    output.append(v)
        elif prev == "--query-output":
            vals=["plain","json","jsonp","jsonl","md","tree","json-pretty"]
            for v in vals:
                if not current or v.startswith(current):
                    output.append(v)
        else:
            for opt in options:
                if not current or opt.startswith(current):
                    output.append(opt)
    else:
        for sc in subcommands:
            if not current or sc.startswith(current):
                output.append(sc)
        dir_part="."
        file_prefix=current
        if "/" in current:
            dir_part=os.path.dirname(current) or "."
            file_prefix=os.path.basename(current)
        try:
            entries=os.listdir(dir_part)
        except:
            entries=[]
        for e in entries:
            full=os.path.join(dir_part, e) if dir_part!="." else e
            if file_prefix and not e.lower().startswith(file_prefix.lower()):
                continue
            p=pathlib.Path(full)
            if p.is_dir():
                disp=full+"/" if not full.endswith("/") else full
                output.append(disp)
            else:
                if e.lower().endswith(".md") or e.lower().endswith(".markdown"):
                    output.append(full)
        if not current:
            output.extend(options)
    return output

