        sys.exit(1)

    if is_count:
        print(render_count(nodes))
        return

    if is_section and not is_query:
        if meta['headingCount']==1 and nodes[0]['title']=="Select a file":
            print(f"Section '{{parsed.section}}' not found", file=sys.stderr)
            sys.exit(1)
        flat=flatten_nodes(nodes)
        target=None
        for n in flat:
            if n['title'].lower() == parsed.section.lower():
                target=n
                break
        if not target:
            print(f"Section '{{parsed.section}}' not found", file=sys.stderr)
            sys.exit(1)
        if target['title']=="Input":
            if target['content_raw']:
                print(f"# Input\\n\\n{{target['content_raw']}}")
            else:
                print(f"# Input")
            return
        idx=None
        for i,h in enumerate(headings):
            if h['line_num']==target['line_num'] and h['title']==target['title']:
                idx=i
                break
        if idx is None:
            print(f"Section '{{parsed.section}}' not found", file=sys.stderr)
            sys.exit(1)
        start=headings[idx]['heading_offset']
        end=len(content)
        for h in headings[idx+1:]:
            if h['level'] <= headings[idx]['level']:
                end=h['heading_offset']
                break
        sec_content=content[start:end].strip()
        print(sec_content)
        return

    if is_query:
        q=parsed.query
        pipeline=[p.strip() for p in q.split('|')]

        def collect_all_blocks(nodes):
            all_b=[]
            flat_nodes=flatten_nodes(nodes)
            for n in flat_nodes:
                bs=parse_blocks(n['content_raw'])
                all_b.extend(bs)
            return all_b

        flat_headings=flatten_nodes(nodes)
        all_blocks=collect_all_blocks(nodes)

        code_blocks=[]
        link_items=[]
        table_items=[]
        list_items=[]
        blockquote_items=[]
        image_items=[]

        for b in all_blocks:
            if b['type']=='code':
                code_blocks.append(b)
            elif b['type']=='table':
                table_items.append(b)
            elif b['type']=='list':
                list_items.append(b)
            elif b['type']=='blockquote':
                blockquote_items.append(b)
            if b['type']=='paragraph':
                for inline in b.get('inline',[]):
                    if inline['type']=='link':
                        url=inline['url']
                        if url.startswith('https://') or url.startswith('http://'):
                            ltype='external'
                        elif url.startswith('#'):
                            ltype='anchor'
                        else:
                            ltype='relative'
                        link_items.append({{
                            'type':'link',
                            'text': inline['text'],
                            'url': url,
                            'link_type': ltype,
                            'raw': f"[{{inline['text']}}]({{inline['url']}})",
                        }})
                    elif inline['type']=='image':
                        image_items.append({{
                            'type':'image',
                            'alt': inline.get('alt',''),
                            'src': inline.get('src',''),
                            'url': inline.get('src',''),
                        }})

        def parse_simple_selector(s):
            s=s.strip()
            is_array=False
            if s.startswith('[') and s.endswith(']'):
                inner=s[1:-1].strip()
                res=parse_simple_selector(inner)
                res['is_array']=True
                return res
            m=re.match(r'^\\.([a-zA-Z0-9]+)(?:\\[(.*)\\])?$', s)
            if not m:
                return {{'kind':'unknown','raw':s}}
            elem_type=m.group(1)
            filt=m.group(2)
            return {{'kind':'selector','type':elem_type.lower(),'filter':filt,'is_array':is_array,'raw':s}}

        def parse_selector(sel):
            sel=sel.strip()
            if sel==".":
                return {{'kind':'doc'}}
            if sel.startswith('[') and sel.endswith(']'):
                inner=sel[1:-1].strip()
                parsed_inner=parse_selector(inner)
                parsed_inner['is_array']=True
                return parsed_inner
            parts=[]
            ops=[]
            current=""
            bracket_depth=0
            i=0
            while i < len(sel):
                c=sel[i]
                if c=='[':
                    bracket_depth+=1
                    current+=c
                    i+=1
                elif c==']':
                    bracket_depth-=1
                    current+=c
                    i+=1
                elif bracket_depth==0 and sel[i:i+2]==">>":
                    parts.append(current.strip())
                    ops.append(">>")
                    current=""
                    i+=2
                elif bracket_depth==0 and c=='>':
                    parts.append(current.strip())
                    ops.append(">")
                    current=""
                    i+=1
                else:
                    current+=c
                    i+=1
            parts.append(current.strip())
            if len(parts)>1:
                parsed_parts=[]
                for p in parts:
                    parsed_parts.append(parse_simple_selector(p))
                return {{'kind':'hierarchy','parts':parsed_parts,'ops':ops}}
            return parse_simple_selector(sel)

        def eval_filter(elem_type, filter_str, items):
            if filter_str is None:
                return items
            filter_str=filter_str.strip()
            if re.match(r'^-?\\d+$', filter_str):
                idx=int(filter_str)
                if idx <0:
                    idx=len(items)+idx
                if 0 <= idx < len(items):
                    return [items[idx]]
                else:
                    return []
            if ':' in filter_str:
                parts=filter_str.split(':')
                if len(parts)==2:
                    s=parts[0].strip()
                    e=parts[1].strip()
                    start=None
                    end=None
                    if s!='':
                        try:
                            start=int(s)
                        except:
                            start=None
                    if e!='':
                        try:
                            end=int(e)
                        except:
                            end=None
                    return items[start:end]
                else:
                    return items
            is_quoted=False
            inner_filter=filter_str
            if (filter_str.startswith('"') and filter_str.endswith('"')) or (filter_str.startswith("'") and filter_str.endswith("'")):
                is_quoted=True
                inner_filter=filter_str[1:-1]
            if elem_type in ['h','heading','h1','h2','h3','h4','h5','h6']:
                res=[]
                for item in items:
                    title=item['node']['title']
                    if is_quoted:
                        if title.lower() == inner_filter.lower():
                            res.append(item)
                    else:
                        if inner_filter.lower() in title.lower():
                            res.append(item)
                return res
            elif elem_type.startswith('code'):
                res=[]
                for item in items:
                    content_text=item.get('block',{{}}).get('content','') or item.get('content','')
                    if is_quoted:
                        if content_text.lower() == inner_filter.lower() or inner_filter.lower() in content_text.lower():
                            res.append(item)
                    else:
                        if inner_filter.lower() in content_text.lower():
                            res.append(item)
                return res
            elif elem_type in ['link','a']:
                known_types=['external','anchor','relative']
                if inner_filter.lower() in known_types and not is_quoted:
                    res=[]
                    for item in items:
                        if item.get('link_type','').lower() == inner_filter.lower():
                            res.append(item)
                    return res
                else:
                    res=[]
                    for item in items:
                        t=item.get('text','')
                        if is_quoted:
                            if t.lower() == inner_filter.lower():
                                res.append(item)
                        else:
                            if inner_filter.lower() in t.lower():
                                res.append(item)
                    return res
            elif elem_type == 'table':
                res=[]
                for item in items:
                    haystack=" ".join(item.get('headers',[])) + " " + " ".join([" ".join(row) for row in item.get('rows',[])])
                    if inner_filter.lower() in haystack.lower():
                        res.append(item)
                return res
            elif elem_type == 'list':
                res=[]
                for item in items:
                    haystack=" ".join([it.get('content','') for it in item.get('items',[])])
                    if inner_filter.lower() in haystack.lower():
                        res.append(item)
                return res
            elif elem_type in ['blockquote','img']:
                res=[]
                for item in items:
                    haystack=item.get('content','') or item.get('text','') or item.get('alt','')
                    if inner_filter.lower() in haystack.lower():
                        res.append(item)
                return res
            else:
                return items

        def get_initial_items(selector_parsed, flat_headings, code_blocks, link_items, table_items, list_items, blockquote_items, image_items, nodes):
            if selector_parsed.get('kind') == 'doc':
                return [{{'type':'doc','nodes':nodes,'flat':flat_headings,'blocks':all_blocks,'meta':meta}}]
            if selector_parsed.get('kind') == 'hierarchy':
                parts=selector_parsed['parts']
                ops=selector_parsed['ops']
                current_items=get_initial_items(parts[0], flat_headings, code_blocks, link_items, table_items, list_items, blockquote_items, image_items, nodes)
                for op, next_part in zip(ops, parts[1:]):
                    next_type=next_part['type']
                    new_items=[]
                    for cur in current_items:
                        if cur['type']!='heading':
                            continue
                        cur_node=cur['node']
                        if next_type in ['h','heading','h1','h2','h3','h4','h5','h6']:
                            expected_level=None
                            if next_type.startswith('h') and next_type[1:].isdigit():
                                expected_level=int(next_type[1])
                            if op=='>':
                                candidates=cur_node['children']
                            else:
                                def collect_desc(n):
                                    res=[]
                                    for ch in n['children']:
                                        res.append(ch)
                                        res.extend(collect_desc(ch))
                                    return res
                                candidates=collect_desc(cur_node)
                            filtered=candidates
                            if expected_level is not None:
                                filtered=[c for c in filtered if c['level']==expected_level]
                            if next_part.get('filter') is not None:
                                heading_elems=[{{'type':'heading','node':c,'text':c['title'],'level':c['level'],'title':c['title'],'line':c['line_num']}} for c in filtered]
                                filtered_elems=eval_filter(next_type, next_part['filter'], heading_elems)
                                filtered=[e['node'] for e in filtered_elems]
                            for cand in filtered:
                                new_items.append({{'type':'heading','node':cand,'level':cand['level'],'text':cand['title'],'line':cand['line_num'],'title':cand['title']}})
                        else:
                            if op=='>':
                                bs=parse_blocks(cur_node['content_raw'])
                                for b in bs:
                                    if next_type.startswith('code') and b['type']=='code':
                                        new_items.append({{'type':'code','block':b,'content':b['content'],'language':b.get('language')}})
                            else:
                                def collect_nodes(n):
                                    res=[n]
                                    for ch in n['children']:
                                        res.extend(collect_nodes(ch))
                                    return res
                                all_desc_nodes=collect_nodes(cur_node)
                                for dn in all_desc_nodes:
                                    bs=parse_blocks(dn['content_raw'])
                                    for b in bs:
                                        if next_type.startswith('code') and b['type']=='code':
                                            new_items.append({{'type':'code','block':b,'content':b['content'],'language':b.get('language')}})
                                        elif next_type in ['link','a'] and b['type']=='paragraph':
                                            for inl in b.get('inline',[]):
                                                if inl['type']=='link':
                                                    url=inl['url']
                                                    ltype='external' if url.startswith('http') else 'anchor' if url.startswith('#') else 'relative'
                                                    new_items.append({{'type':'link','text':inl['text'],'url':url,'link_type':ltype}})
                    if next_type not in ['h','heading','h1','h2','h3','h4','h5','h6']:
                        if next_part.get('filter') is not None:
                            new_items=eval_filter(next_type, next_part['filter'], new_items)
                    current_items=new_items
                return current_items

            elem_type=selector_parsed.get('type','')
            filt=selector_parsed.get('filter')

            if elem_type in ['h','heading']:
                items=[{{'type':'heading','node':n,'level':n['level'],'text':n['title'],'line':n['line_num'],'title':n['title']}} for n in flat_headings]
                items=eval_filter(elem_type, filt, items)
                return items
            elif elem_type.startswith('h') and elem_type[1:].isdigit():
                lvl=int(elem_type[1])
                items=[{{'type':'heading','node':n,'level':n['level'],'text':n['title'],'line':n['line_num'],'title':n['title']}} for n in flat_headings if n['level']==lvl]
                items=eval_filter(elem_type, filt, items)
                return items
            elif elem_type == 'code':
                elems=[]
                for b in code_blocks:
                    elems.append({{'type':'code','block':b,'content':b['content'],'language':b.get('language'),'text':b['content']}})
                elems=eval_filter(elem_type, filt, elems)
                return elems
            elif elem_type in ['link','a']:
                elems=[]
                for l in link_items:
                    elems.append(l)
                elems=eval_filter(elem_type, filt, elems)
                return elems
            elif elem_type == 'table':
                elems=[]
                for t in table_items:
                    elems.append({{'type':'table','headers':t['headers'],'rows':t['rows'],'block':t}})
                elems=eval_filter(elem_type, filt, elems)
                return elems
            elif elem_type == 'list':
                elems=[]
                for li in list_items:
                    elems.append({{'type':'list','block':li,'items':li.get('items',[]),'ordered':li.get('ordered',False)}})
                elems=eval_filter(elem_type, filt, elems)
                return elems
            elif elem_type == 'blockquote':
                elems=[]
                for b in blockquote_items:
                    elems.append({{'type':'blockquote','block':b,'content':b.get('content','')}})
                elems=eval_filter(elem_type, filt, elems)
                return elems
            elif elem_type == 'img':
                elems=[]
                for img in image_items:
                    elems.append({{'type':'image','alt':img.get('alt',''),'src':img.get('src',''),'url':img.get('src','')}})
                elems=eval_filter(elem_type, filt, elems)
                return elems
            else:
                return []

        first_sel_str=pipeline[0]
        first_parsed=parse_selector(first_sel_str)
        current= get_initial_items(first_parsed, flat_headings, code_blocks, link_items, table_items, list_items, blockquote_items, image_items, nodes)

        is_array_mode = False
        if pipeline[0].strip().startswith('['):
            is_array_mode=True

        for part in pipeline[1:]:
            part=part.strip()
            def elem_text(e):
                if e['type']=='heading':
                    return e['node']['title']
                elif e['type']=='code':
                    return e.get('content','')
                elif e['type']=='link':
                    return e.get('text','')
                elif e['type']=='table':
                    return "Table"
                elif e['type']=='list':
                    return " ".join([it.get('content','') for it in e.get('items',[])])
                elif e['type']=='blockquote':
                    return e.get('content','')
                elif e['type']=='text':
                    return e.get('text','')
                elif e['type']=='number':
                    return str(e.get('value',''))
                else:
                    return str(e)

            m=re.match(r'^([a-zA-Z_]+)(?:\\((.*)\\))?$', part)
            if not m:
                continue
            fname=m.group(1).lower()
            fargs=m.group(2)

            if fname in ['count','length','len','size']:
                if is_array_mode:
                    cnt=len(current)
                    current=[{{'type':'number','value':cnt,'text':str(cnt)}}]
                    is_array_mode=False
                else:
                    new=[]
                    for el in current:
                        new.append({{'type':'number','value':1,'text':'1'}})
                    current=new
                continue
            if fname in ['first','head']:
                if is_array_mode and current:
                    current=[current[0]]
                    is_array_mode=False
                continue
            if fname == 'last':
                if is_array_mode and current:
                    current=[current[-1]]
                    is_array_mode=False
                continue
            if fname == 'nth':
                if is_array_mode:
                    try:
                        n=int(fargs.strip()) if fargs else 0
                        if n<0:
                            n=len(current)+n
                        if 0 <= n < len(current):
                            current=[current[n]]
                        else:
                            current=[]
                    except:
                        current=[]
                    is_array_mode=False
                continue
            if fname in ['limit','take']:
                if is_array_mode:
                    try:
                        n=int(fargs.strip()) if fargs else 0
                        current=current[:n]
                    except:
                        pass
                continue
            if fname in ['skip','drop']:
                if is_array_mode:
                    try:
                        n=int(fargs.strip()) if fargs else 0
                        current=current[n:]
                    except:
                        pass
                continue
            if fname == 'reverse':
                if is_array_mode:
                    current=list(reversed(current))
                continue
            if fname == 'sort':
                if is_array_mode:
                    current=sorted(current, key=lambda e: elem_text(e).lower())
                continue
            if fname == 'unique':
                seen=set()
                uniq=[]
                for e in current:
                    t=elem_text(e).lower()
                    if t not in seen:
                        seen.add(t)
                        uniq.append(e)
                if is_array_mode:
                    current=uniq
                continue
            if fname == 'group_by':
                if not is_array_mode:
                    continue
                key=fargs.strip().strip('"').strip("'") if fargs else ""
                groups={{}}
                for e in current:
                    if key=="level" and e['type']=='heading':
                        lvl=e['level']
                        k=f"h{{lvl}}"
                    else:
                        k=elem_text(e)
                    groups.setdefault(k, []).append(e)
                current=[{{'type':'grouped','groups':groups}}]
                is_array_mode=False
                continue
            if fname in ['text']:
                new=[]
                for e in current:
                    if e['type']=='heading':
                        txt=e['node']['title']
                    elif e['type']=='code':
                        txt=e.get('content','')
                    elif e['type']=='link':
                        txt=e.get('text','')
                    elif e['type']=='table':
                        txt="Table"
                    elif e['type']=='list':
                        txt=" ".join([it.get('content','') for it in e.get('items',[])])
                    elif e['type']=='number':
                        txt=str(e.get('value',''))
                    elif e['type']=='text':
                        txt=e.get('text','')
                    else:
                        txt=elem_text(e)
                    new.append({{'type':'text','text':txt,'value':txt}})
                current=new
                is_array_mode=False
                continue
            if fname in ['upper']:
                new=[]
                for e in current:
                    if e['type']=='text':
                        txt=e['text'].upper()
                        new.append({{'type':'text','text':txt,'value':txt}})
                    elif e['type']=='heading':
                        txt=e['node']['title'].upper()
                        new.append({{'type':'text','text':txt,'value':txt}})
                    else:
                        txt=elem_text(e).upper()
                        new.append({{'type':'text','text':txt,'value':txt}})
                current=new
                continue
            if fname in ['lower']:
                new=[]
                for e in current:
                    if e['type']=='text':
                        txt=e['text'].lower()
                        new.append({{'type':'text','text':txt,'value':txt}})
                    elif e['type']=='heading':
                        txt=e['node']['title'].lower()
                        new.append({{'type':'text','text':txt,'value':txt}})
                    else:
                        txt=elem_text(e).lower()
                        new.append({{'type':'text','text':txt,'value':txt}})
                current=new
                continue
            if fname == 'slugify':
                new=[]
                for e in current:
                    if e['type']=='heading':
                        txt=slugify(e['node']['title'])
                    elif e['type']=='text':
                        txt=slugify(e['text'])
                    else:
                        txt=slugify(elem_text(e))
                    new.append({{'type':'text','text':txt,'value':txt}})
                current=new
                continue
            if fname == 'trim':
                new=[]
                for e in current:
                    if e['type']=='text':
                        txt=e['text'].strip()
                        new.append({{'type':'text','text':txt,'value':txt}})
                    elif e['type']=='heading':
                        txt=e['node']['title'].strip()
                        new.append({{'type':'text','text':txt,'value':txt}})
                    else:
                        txt=elem_text(e).strip()
                        new.append({{'type':'text','text':txt,'value':txt}})
                current=new
                continue
            if fname in ['content']:
                new=[]
                for e in current:
                    if e['type']=='heading':
                        raw=e['node']['content_raw']
                        new.append({{'type':'text','text':raw,'value':raw}})
                    elif e['type']=='code':
                        raw=e.get('content','')
                        new.append({{'type':'text','text':raw,'value':raw}})
                    else:
                        txt=elem_text(e)
                        new.append({{'type':'text','text':txt,'value':txt}})
                current=new
                continue
            if fname == 'md':
                new=[]
                for e in current:
                    if e['type']=='heading':
                        target_node=e['node']
                        idx=None
                        for i,h in enumerate(headings):
                            if h['line_num']==target_node['line_num'] and h['title']==target_node['title']:
                                idx=i
                                break
                        if idx is not None:
                            start=headings[idx]['heading_offset']
                            end=len(content)
                            for h in headings[idx+1:]:
                                if h['level'] <= headings[idx]['level']:
                                    end=h['heading_offset']
                                    break
                            sec_md=content[start:end].strip()
                            new.append({{'type':'text','text':sec_md,'value':sec_md,'is_md':True}})
                        else:
                            new.append({{'type':'text','text':e['node']['content_raw'],'value':e['node']['content_raw']}})
                    elif e['type']=='code':
                        lang=e.get('language') or ''
                        cont=e.get('content','')
                        md_text=f"```{{lang}}\\n{{cont}}\\n```"
                        new.append({{'type':'text','text':md_text,'value':md_text,'is_md':True}})
                    elif e['type']=='link':
                        md_text=f"[{{e.get('text','')}}]({{e.get('url','')}})"
                        new.append({{'type':'text','text':md_text,'value':md_text}})
                    else:
                        new.append(e)
                current=new
                continue
            if fname in ['url','href','src']:
                new=[]
                for e in current:
                    if e['type']=='link':
                        txt=e.get('url','')
                        new.append({{'type':'text','text':txt,'value':txt}})
                    elif e['type']=='image':
                        txt=e.get('src','') or e.get('url','')
                        new.append({{'type':'text','text':txt,'value':txt}})
                current=new
                continue
            if fname == 'lang':
                new=[]
                for e in current:
                    if e['type']=='code':
                        txt=e.get('language') or ''
                        if txt:
                            new.append({{'type':'text','text':txt,'value':txt}})
                current=new
                continue
            if fname in ['stats']:
                hcount=len(flat_headings)
                ccount=len(code_blocks)
                lcount=len(link_items)
                icount=len(image_items)
                tcount=len(table_items)
                lstcount=len(list_items)
                words=meta['wordCount']
                stats_text=f"headings: {{hcount}}\\ncode_blocks: {{ccount}}\\nlinks: {{lcount}}\\nimages: {{icount}}\\ntables: {{tcount}}\\nlists: {{lstcount}}\\nwords: {{words}}"
                current=[{{'type':'stats','text':stats_text,'value':stats_text,'meta':{{'headings':hcount,'code_blocks':ccount,'links':lcount,'images':icount,'tables':tcount,'lists':lstcount,'words':words}}}}]
                is_array_mode=False
                continue
            if fname == 'levels':
                counts={{}}
                for h in flat_headings:
                    lvl=h['level']
                    counts[lvl]=counts.get(lvl,0)+1
                lines=[]
                for lvl in sorted(counts.keys()):
                    lines.append(f"h{{lvl}}: {{counts[lvl]}}")
                txt="\\n".join(lines)
                current=[{{'type':'levels','text':txt,'counts':counts}}]
                continue
            if fname == 'langs':
                counts={{}}
                for b in code_blocks:
                    lang=b.get('language') or ''
                    if lang:
                        counts[lang]=counts.get(lang,0)+1
                lines=[]
                for lang,cnt in sorted(counts.items()):
